package com.mirrly.tgproxy.core

/**
 * Модель встроенного VPN-сервера (14 эталонных конфигураций AmneziaWG).
 */
data class BuiltinVpnServerItem(
    val id: String,
    val name: String,
    val countryCode: String,
    val endpoint: String,
    val isTel: Boolean = false,
    val speedLimitText: String? = if (isTel) "Лимит 25 Мбит/с" else null,
    val isAnycast: Boolean = false,
    val rawConfig: String
) {
    fun parseProfile(): WarpProfile? {
        val result = WarpProfileParser.parse(rawConfig)
        return if (result is WarpImportResult.Success) result.profile else null
    }
}

